INSERT INTO `int_job` (`id`, `tenant_id`, `code`, `name`, `cn_name`, `job_type`, `engine`, `status`, `schedule_type`, `cron`, `interval_min`, `priority`, `timeout_min`, `retry`, `industry`, `dsl`, `script_lang`, `script`, `owner`, `description`, `version`, `last_run_time`, `next_run_time`, `success_count`, `fail_count`, `create_time`) VALUES (1,1,'JOB-CUST-DIM','客户维度加工','客户维度加工','ETL','BATCH','PUBLISHED','CRON','1440',1440,5,60,2,'GOV','{\"dslVersion\":\"1.0\",\"nodes\":[{\"id\":\"src\",\"type\":\"SOURCE\",\"name\":\"dwd_customer_dim\",\"table\":\"dwd_customer_dim\"},{\"id\":\"m1\",\"type\":\"FIELD_MAP\",\"name\":\"字段映射\"},{\"id\":\"sink\",\"type\":\"SINK\",\"name\":\"dwd_customer_dim\",\"table\":\"dwd_customer_dim\"}],\"edges\":[{\"from\":\"src\",\"to\":\"m1\"},{\"from\":\"m1\",\"to\":\"sink\"}]}','SQL','DELETE FROM dwd_customer_dim;INSERT INTO dwd_customer_dim(customer_key,customer_id,cust_name,gender,age,phone,email,city,reg_date,member_level,is_valid) SELECT CONCAT(\'CK\', customer_id), customer_id, cust_name, gender, EXTRACT(YEAR FROM CURRENT_DATE) - EXTRACT(YEAR FROM birthday), phone, email, city, CAST(reg_time AS DATE), member_level, CASE WHEN phone IS NULL OR city IS NULL THEN 0 ELSE 1 END FROM ods_customer','张三','每日 02:15 将 ODS 客户加工为客户维度','1.0.0','2026-10-21 13:21:00','2026-10-22 13:21:00',47,3,'2026-09-21 13:20:47'),(2,1,'JOB-ORDER-FACT','订单事实加工','订单事实加工','ETL','BATCH','PUBLISHED','CRON','60',60,5,60,2,'GOV','{\"dslVersion\":\"1.0\",\"nodes\":[{\"id\":\"src\",\"type\":\"SOURCE\",\"name\":\"ods_order\",\"table\":\"ods_order\"},{\"id\":\"j1\",\"type\":\"JOIN\",\"name\":\"关联产品维\"},{\"id\":\"m1\",\"type\":\"FIELD_MAP\",\"name\":\"金额与日期标准化\"},{\"id\":\"sink\",\"type\":\"SINK\",\"name\":\"dwd_order_fact\",\"table\":\"dwd_order_fact\"}],\"edges\":[{\"from\":\"src\",\"to\":\"j1\"},{\"from\":\"j1\",\"to\":\"m1\"},{\"from\":\"m1\",\"to\":\"sink\"}]}','SQL','DELETE FROM dwd_order_fact;INSERT INTO dwd_order_fact(order_key,order_id,customer_id,product_id,amount,quantity,order_date,pay_date,status,region,channel,is_refund) SELECT CONCAT(\'OK\', order_id), order_id, customer_id, product_id, amount, quantity, CAST(order_time AS DATE), CAST(pay_time AS DATE), status, region, channel, CASE WHEN status=\'退款中\' THEN 1 ELSE 0 END FROM ods_order','张三','每小时加工订单事实并关联产品维度','1.0.0','2026-10-21 15:22:42','2026-10-21 16:22:42',49,3,'2026-09-21 13:20:47'),(3,1,'JOB-PAY-SYNC','支付流水同步','支付流水同步','ETL','BATCH','PUBLISHED','CRON','5',5,5,60,2,'GOV','{\"dslVersion\":\"1.0\",\"nodes\":[{\"id\":\"src\",\"type\":\"SOURCE\",\"name\":\"ods_payment\",\"table\":\"ods_payment\"},{\"id\":\"v1\",\"type\":\"VALIDATE\",\"name\":\"支付金额一致性校验\"},{\"id\":\"sink\",\"type\":\"SINK\",\"name\":\"dwd_order_fact\",\"table\":\"dwd_order_fact\"}],\"edges\":[{\"from\":\"src\",\"to\":\"v1\"},{\"from\":\"v1\",\"to\":\"sink\"}]}','SQL','UPDATE dwd_order_fact SET status=\'已支付\' WHERE status=\'待支付\' AND order_id IN (SELECT order_id FROM ods_payment WHERE status=\'成功\')','张三','准实时同步支付流水并回写订单状态','1.0.0','2026-10-21 15:27:43','2026-10-21 15:32:43',70,3,'2026-09-21 13:20:47'),(4,1,'JOB-ORDER-SUM','订单日汇总','订单日汇总','ETL','BATCH','PUBLISHED','CRON','1440',1440,5,60,2,'GOV','{\"dslVersion\":\"1.0\",\"nodes\":[{\"id\":\"src\",\"type\":\"SOURCE\",\"name\":\"dwd_order_fact\",\"table\":\"dwd_order_fact\"},{\"id\":\"a1\",\"type\":\"AGGREGATE\",\"name\":\"按日-区域-渠道聚合\"},{\"id\":\"sink\",\"type\":\"SINK\",\"name\":\"dws_order_summary\",\"table\":\"dws_order_summary\"}],\"edges\":[{\"from\":\"src\",\"to\":\"a1\"},{\"from\":\"a1\",\"to\":\"sink\"}]}','SQL','DELETE FROM dws_order_summary;INSERT INTO dws_order_summary(stat_date,region,channel,order_cnt,amount,refund_amt) SELECT order_date, region, channel, COUNT(*), SUM(amount), SUM(CASE WHEN is_refund=1 THEN amount ELSE 0 END) FROM dwd_order_fact GROUP BY order_date, region, channel','张三','按区域/渠道汇总订单与退款','1.0.0','2026-10-21 13:32:47','2026-10-22 13:32:47',47,3,'2026-09-21 13:20:47'),(5,1,'JOB-CUST-VALUE','客户价值计算','客户价值计算','ETL','BATCH','PUBLISHED','CRON','1440',1440,5,60,2,'GOV','{\"dslVersion\":\"1.0\",\"nodes\":[{\"id\":\"src\",\"type\":\"SOURCE\",\"name\":\"dwd_order_fact\",\"table\":\"dwd_order_fact\"},{\"id\":\"j1\",\"type\":\"JOIN\",\"name\":\"关联客户维度\"},{\"id\":\"a1\",\"type\":\"AGGREGATE\",\"name\":\"客户粒度聚合\"},{\"id\":\"sink\",\"type\":\"SINK\",\"name\":\"dws_customer_value\",\"table\":\"dws_customer_value\"}],\"edges\":[{\"from\":\"src\",\"to\":\"j1\"},{\"from\":\"j1\",\"to\":\"a1\"},{\"from\":\"a1\",\"to\":\"sink\"}]}','SQL','DELETE FROM dws_customer_value;INSERT INTO dws_customer_value(customer_id,total_amount,order_cnt,last_order_date,value_level) SELECT customer_id, SUM(amount), COUNT(*), MAX(order_date), CASE WHEN COUNT(*)>20 THEN \'高价值\' WHEN COUNT(*)>8 THEN \'中价值\' ELSE \'普通\' END FROM dwd_order_fact GROUP BY customer_id','张三','计算客户累计消费、订单数与价值分层','1.0.0','2026-10-21 13:32:06','2026-10-22 13:32:06',47,3,'2026-09-21 13:20:47'),(6,1,'JOB-REGION-SALES','区域销售与驾驶舱','区域销售与驾驶舱','ETL','BATCH','PUBLISHED','CRON','1440',1440,5,60,2,'GOV','{\"dslVersion\":\"1.0\",\"nodes\":[{\"id\":\"src\",\"type\":\"SOURCE\",\"name\":\"dwd_order_fact\",\"table\":\"dwd_order_fact\"},{\"id\":\"a1\",\"type\":\"AGGREGATE\",\"name\":\"区域达成\"},{\"id\":\"a2\",\"type\":\"AGGREGATE\",\"name\":\"驾驶舱指标\"},{\"id\":\"sink\",\"type\":\"SINK\",\"name\":\"dws_region_sales\",\"table\":\"dws_region_sales\"}],\"edges\":[{\"from\":\"src\",\"to\":\"a1\"},{\"from\":\"src\",\"to\":\"a2\"},{\"from\":\"a1\",\"to\":\"sink\"},{\"from\":\"a2\",\"to\":\"sink2\"}]}','SQL','DELETE FROM dws_region_sales;INSERT INTO dws_region_sales(stat_date,region,sales_amount,target_amount,completion_rate) SELECT order_date, region, SUM(amount), SUM(amount)*1.05, SUM(amount)/(SUM(amount)*1.05) FROM dwd_order_fact GROUP BY order_date, region;DELETE FROM ads_sales_dashboard;INSERT INTO ads_sales_dashboard(stat_date,total_amount,order_cnt,customer_cnt,avg_order_amount,refund_rate) SELECT order_date, SUM(amount), COUNT(*), COUNT(DISTINCT customer_id), SUM(amount)/COUNT(*), SUM(CASE WHEN is_refund=1 THEN amount ELSE 0 END)/SUM(amount) FROM dwd_order_fact GROUP BY order_date','张三','生成区域达成与销售驾驶舱指标','1.0.0','2026-10-21 13:32:07','2026-10-22 13:32:07',47,3,'2026-09-21 13:20:47'),(7,1,'JOB-DEVICE-FACT','设备事实加工','设备事实加工','ETL','BATCH','PUBLISHED','CRON','5',5,5,60,2,'GOV','{\"dslVersion\":\"1.0\",\"nodes\":[{\"id\":\"src\",\"type\":\"SOURCE\",\"name\":\"ods_device_metric\",\"table\":\"ods_device_metric\"},{\"id\":\"f1\",\"type\":\"FILTER\",\"name\":\"剔除空值与越界\"},{\"id\":\"m1\",\"type\":\"TYPE_CONVERT\",\"name\":\"精度归一\"},{\"id\":\"sink\",\"type\":\"SINK\",\"name\":\"dwd_device_fact\",\"table\":\"dwd_device_fact\"}],\"edges\":[{\"from\":\"src\",\"to\":\"f1\"},{\"from\":\"f1\",\"to\":\"m1\"},{\"from\":\"m1\",\"to\":\"sink\"}]}','SQL','DELETE FROM dwd_device_fact WHERE collect_date = CURRENT_DATE;INSERT INTO dwd_device_fact(device_key,device_id,workshop,metric_name,metric_value,collect_date) SELECT CONCAT(CONCAT(CONCAT(\'DK\', device_id), \'-\'), CONCAT(metric_name, CONCAT(\'-\', TIMESTAMPDIFF(MINUTE, CAST(collect_time AS DATE), collect_time)))), device_id, workshop, metric_name, metric_value, CAST(collect_time AS DATE) FROM ods_device_metric WHERE metric_value BETWEEN -100 AND 200 AND CAST(collect_time AS DATE)=CURRENT_DATE','张三','分钟级清洗设备时序并落入设备事实表','1.0.0','2026-10-21 15:25:43','2026-10-21 15:30:43',68,3,'2026-09-21 13:20:47'),(8,1,'WF-SALES-DAILY','销售域日批工作流','销售域日批工作流','WORKFLOW','BATCH','PUBLISHED','CRON','0 0 2 * * ?',1440,8,180,1,'GOV','[{\"key\":\"n1\",\"upstream\":[],\"jobCode\":\"JOB-CUST-DIM\"},{\"key\":\"n2\",\"upstream\":[],\"jobCode\":\"JOB-ORDER-FACT\"},{\"key\":\"n3\",\"upstream\":[\"n2\"],\"jobCode\":\"JOB-PAY-SYNC\"},{\"key\":\"n4\",\"upstream\":[\"n2\",\"n3\"],\"jobCode\":\"JOB-ORDER-SUM\"},{\"key\":\"n5\",\"upstream\":[\"n1\",\"n2\"],\"jobCode\":\"JOB-CUST-VALUE\"},{\"key\":\"n6\",\"upstream\":[\"n4\"],\"jobCode\":\"JOB-REGION-SALES\"}]','SHELL',NULL,'张三','客户-订单-支付-汇总-驾驶舱的依赖编排，失败自动重试 1 次，超时 180 分钟','1.0.0',NULL,'2026-10-21 16:20:47',58,2,'2026-09-11 13:20:47');
