,'L1','行标'),(17,1,'RETAIL','RET_SKU','单品',NULL,'库存管理的最小产品单元','(?i).*(sku|product|item).*','DE_PRODUCT_ID','货品;商品','L1','行标'),(18,1,'RETAIL','RET_STORE','门店',NULL,'开展零售经营的实体或虚拟门店','(?i).*(store|shop).*','DE_CITY','网点;店铺','L1','行标'),(19,1,'RETAIL','RET_GMV','商品交易总额',NULL,'统计周期内成交订单金额合计','(?i).*(gmv|amount|sales).*','DE_AMOUNT','成交额','L2','行标'),(20,1,'RETAIL','RET_STOCK','库存周转天数',NULL,'平均库存除以日均销售成本','(?i).*(stock|inventory).*','DE_PRODUCT_ID','周转;库存','L1','行标');
