t','pay_amount','ACCURACY','CONSISTENCY','SELECT COUNT(*) FROM ods_payment p JOIN ods_order o ON p.order_id=o.order_id WHERE ABS(p.pay_amount-o.amount) > 0.01',0.0800,2.00,'MAJOR','ENABLED','GOV','赵安全','DAILY','FULL',1,16088,86,99.47,'2026-10-21 13:20:50','2026-10-01 13:20:49'),(14,1,'QR-20261021132048-1014','产品售价不低于成本',13,'ods_product','price','ACCURACY','RANGE','SELECT COUNT(*) FROM ods_product WHERE price < cost',0.0800,1.00,'MINOR','ENABLED','GOV','王武','DAILY','FULL',1,320,11,96.56,'2026-10-21 13:20:50','2026-10-01 13:20:49'),(15,1,'QR-20261021132048-1015','客户邮箱格式合法',8,'ods_customer','email','VALIDITY','REGEX','SELECT COUNT(*) FROM ods_customer WHERE email IS NOT NULL AND email NOT LIKE \'%_@_%._%\'',0.1600,1.00,'MINOR','ENABLED','GOV','刘琴','DAILY','FULL',1,6000,127,97.88,'2026-10-21 15:10:40','2026-10-01 13:20:49'),(16,1,'QR-20261021132048-1016','客户性别枚举合法',8,'ods_customer','gender','VALIDITY','ENUM','SELECT COUNT(*) FROM ods_customer WHERE gender NOT IN (\'男\',\'女\')',0.0800,1.00,'MAJOR','ENABLED','GOV','刘琴','DAILY','FULL',1,6000,45,99.25,'2026-10-21 15:10:40','2026-10-01 13:20:49'),(17,1,'QR-20261021132048-1017','政务证件号长度合法',10,'ods_gov_population','id_card','VALIDITY','REGEX','SELECT COUNT(*) FROM ods_gov_population WHERE id_card IS NOT NULL AND LENGTH(id_card)<>18',0.1600,2.00,'CRITICAL','ENABLED','GOV','陈顾问','DAILY','FULL',1,5000,40,99.20,'2026-10-21 13:20:51','2026-10-01 13:20:49'),(18,1,'QR-20261021132048-1018','客户生日不得超当前日期',8,'ods_customer','birthday','VALIDITY','RANGE','SELECT COUNT(*) FROM ods_customer WHERE birthday > CURRENT_DATE',0.0400,1.00,'MAJOR','ENABLED','GOV','刘琴','DAILY','FULL',1,6000,61,98.98,'2026-10-21 15:10:40','2026-10-01 13:20:49'),(19,1,'QR-20261021132048-1019','订单状态枚举合法',11,'ods_order','status','VALIDITY','ENUM','SELECT COUNT(*) FROM ods_order WHERE status NOT IN (\'待支付\',\'已支付\',\'已发货\',\'已完成\',\'已取消\',\'退款中\')',0.0400,1.00,'MAJOR','ENABLED','GOV','王武','DAILY','FULL',1,24000,59,99.75,'2026-10-21 13:20:50','2026-10-01 13:20:49'),(20,1,'QR-20261021132048-1020','设备指标量程合法',9,'ods_device_metric','metric_value','ACCURACY','RANGE','SELECT COUNT(*) FROM ods_device_metric WHERE metric_value < -100 OR metric_value > 200',0.1600,2.00,'MAJOR','ENABLED','GOV','李工','DAILY','FULL',1,12000,200,98.33,'2026-10-21 13:20:51','2026-10-01 13:20:49'),(21,1,'QR-20261021132048-1021','设备采集时效',9,'ods_device_metric','collect_time','TIMELINESS','TIMELINESS','SELECT COUNT(*) FROM ods_device_metric WHERE collect_time < ${now-minus-minutes:60} AND collect_time > ${now-minus-minutes:1440}',0.4000,2.00,'MAJOR','ENABLED','GOV','李工','DAILY','FULL',1,12000,10860,9.50,'2026-10-21 13:20:50','2026-10-01 13:20:49'),(22,1,'QR-20261021132048-1022','订单入库时效',11,'ods_order','order_time','TIMELINESS','TIMELINESS','SELECT CASE WHEN EXISTS(SELECT 1 FROM ods_order WHERE order_time > ${now-minus-minutes:120}) THEN 0 ELSE 1 END',0.4000,1.00,'MINOR','ENABLED','GOV','张三','DAILY','FULL',1,24000,0,100.00,'2026-10-21 13:20:50','2026-10-01 13:20:49'),(23,1,'QR-20261021132048-1023','订单事实与源表行数一致',4,'dwd_order_fact','order_id','CONSISTENCY','CONSISTENCY','SELECT CASE WHEN a<>b THEN 1 ELSE 0 END FROM (SELECT (SELECT COUNT(*) FROM dwd_order_fact) a, (SELECT COUNT(*) FROM ods_order WHERE status<>\'已取消\') b) t',0.0200,2.00,'CRITICAL','ENABLED','GOV','张三','DAILY','FULL',1,NULL,NULL,NULL,NULL,'2026-10-01 13:20:49'),(24,1,'QR-20261021132048-1024','客户维度与源表行数一致',2,'dwd_customer_dim','customer_id','CONSISTENCY','CONSISTENCY','SELECT CASE WHEN a<>b THEN 1 ELSE 0 END FROM (SELECT (SELECT COUNT(*) FROM dwd_customer_dim) a, (SELECT COUNT(*) FROM ods_customer) b) t',0.0200,2.00,'MAJOR','ENABLED','GOV','张三','DAILY','FULL',1,6000,0,100.00,'2026-10-21 15:10:41','2026-10-01 13:20:49'),(25,1,'QR-20261021135652-1001','验收规则-手机号非空',8,'ods_customer','phone','COMPLETENESS','NULL_CHECK','SELECT COUNT(*) FROM ods_customer WHERE phone IS NULL',0.0100,1.00,'MAJOR','ENABLED','GOV','liuqin','DAILY','FULL',1,6000,181,96.98,'2026-10-21 13:56:56','2026-10-21 13:56:52');
