INSERT INTO `qa_rule_template` (`id`, `code`, `name`, `industry`, `dimension`, `rule_type`, `expression`, `applies_to`, `description`, `status`) VALUES (1,'TPL_NOT_NULL','非空校验模板','*','COMPLETENESS','NOT_NULL','SELECT COUNT(*) FROM ${table} WHERE ${column} IS NULL OR TRIM(${column})=\'\'','.*','核心字段不允许为空','ENABLED'),(2,'TPL_UNIQUE','唯一性校验模板','*','UNIQUENESS','UNIQUE','SELECT COUNT(*) FROM (SELECT ${column} FROM ${table} WHERE ${column} IS NOT NULL GROUP BY ${column} HAVING COUNT(*)>1) t','.*_id|.*_no','业务主键不得重复','ENABLED'),(3,'TPL_REGEX_MOBILE','手机号格式模板','*','VALIDITY','REGEX','SELECT COUNT(*) FROM ${table} WHERE ${column} IS NOT NULL AND ${column} NOT LIKE \'1%\'','.*phone.*','符合 1[3-9] 号段','ENABLED'),(4,'TPL_ID_CARD','证件号码合规模板','GOV','VALIDITY','REGEX','SELECT COUNT(*) FROM ${table} WHERE ${column} IS NOT NULL AND LENGTH(${column})<>18','.*id_card.*','18 位居民身份证','ENABLED'),(5,'TPL_AMOUNT_RANGE','金额区间模板','FINANCE','ACCURACY','RANGE','SELECT COUNT(*) FROM ${table} WHERE ${column} < 0 OR ${column} > 100000','.*amount.*','金额 0~100000','ENABLED'),(6,'TPL_ENUM','枚举取值模板','*','VALIDITY','ENUM','SELECT COUNT(*) FROM ${table} WHERE ${column} NOT IN (\'男\',\'女\')','.*gender.*','取值必须在枚举内','ENABLED'),(7,'TPL_TIMELINESS','时效性模板','INDUSTRY','TIMELINESS','TIMELINESS','SELECT COUNT(*) FROM ${table} WHERE ${column} < ${now-minus-minutes:60}','.*_time','采集/入库延迟≤60分钟','ENABLED'),(8,'TPL_CONSISTENCY','跨表一致性模板','FINANCE','CONSISTENCY','CONSISTENCY','SELECT CASE WHEN a<>b THEN 1 ELSE 0 END FROM (SELECT (SELECT COUNT(*) FROM ${table}) a, (SELECT COUNT(*) FROM ${ref_table}) b) t','.*_fact','上下游行数一致','ENABLED'),(9,'TPL_PRICE_COST','价格成本模板','RETAIL','ACCURACY','RANGE','SELECT COUNT(*) FROM ${table} WHERE price < cost','.*product.*','售价不得低于成本','ENABLED'),(10,'TPL_FUTURE_DATE','未来日期模板','*','VALIDITY','RANGE','SELECT COUNT(*) FROM ${table} WHERE ${column} > CURRENT_DATE','.*birthday|.*_date','不允许未来日期','ENABLED'),(11,'TELECOM_BSS_-642960058','用户数据一致性','TELECOM','CONSISTENCY','CONSISTENCY','SELECT COUNT(*) FROM ${table} WHERE cust_id IS NULL','.*cust.*','行业包导入模板','ENABLED'),(12,'TELECOM_BSS_311761834','网络指标时效性','TELECOM','TIMELINESS','TIMELINESS','SELECT COUNT(*) FROM ${table} WHERE collect_time < ${now-minus-minutes:15}','.*metric.*','行业包导入模板','ENABLED'),(13,'TELECOM_BSS_1247456703','经营分析准确性','TELECOM','ACCURACY','ACCURACY','SELECT COUNT(*) FROM ${table} WHERE amount < 0','.*amount.*','行业包导入模板','ENABLED'),(14,'GOV_PUBLIC_-1641045761','政务数据完整性','GOV','COMPLETENESS','COMPLETENESS','SELECT COUNT(*) FROM ${table} WHERE id_card IS NULL','.*pop.*','行业包导入模板','ENABLED'),(15,'GOV_PUBLIC_764571917','跨部门数据一致性','GOV','CONSISTENCY','CONSISTENCY','SELECT COUNT(*) FROM ${table} a WHERE NOT EXISTS(SELECT 1 FROM ${ref_table} b WHERE b.id_card=a.id_card)','.*pop.*','行业包导入模板','ENABLED'),(16,'GOV_PUBLIC_-2145005477','数据更新时效性','GOV','TIMELINESS','TIMELINESS','SELECT COUNT(*) FROM ${table} WHERE update_time < ${now-minus-minutes:1440}','.*pop.*','行业包导入模板','ENABLED');
/*!40000 ALTER TABLE `qa_rule_template` ENABLE KEYS */;

