D','1.0.0','数据标准组','2026-10-21 13:20:17'),(13,1,'DE_ORDER_STATUS','status','订单状态','交易','STRING','16','枚举','订单生命周期状态','取值在枚举内','行标','RETAIL','PUBLISHED','1.0.0','数据标准组','2026-10-21 13:20:17'),(14,1,'DE_PAY_TIME','pay_time','支付时间','交易','TIMESTAMP','19','yyyy-MM-dd HH:mm:ss','订单支付完成时间','已支付订单必填','行标','FINANCE','PUBLISHED','1.0.0','数据标准组','2026-10-21 13:20:17'),(15,1,'DE_PRODUCT_ID','product_id','产品标识','产品','STRING','32','字母数字','产品唯一标识','非空','行标','RETAIL','PUBLISHED','1.0.0','数据标准组','2026-10-21 13:20:17'),(16,1,'DE_PRODUCT_NAME','product_name','产品名称','产品','STRING','128','中文/英文','产品对外名称','长度≤128','行标','RETAIL','PUBLISHED','1.0.0','数据标准组','2026-10-21 13:20:17'),(17,1,'DE_CATEGORY','category','产品分类','产品','STRING','32','枚举','产品所属分类','引用分类字典','行标','RETAIL','PUBLISHED','1.0.0','数据标准组','2026-10-21 13:20:17'),(18,1,'DE_PRICE','price','单价','产品','DECIMAL','12,2','非负小数','产品标准售价','≥0','行标','RETAIL','PUBLISHED','1.0.0','数据标准组','2026-10-21 13:20:17'),(19,1,'DE_COST','cost','成本价','产品','DECIMAL','12,2','非负小数','产品单位成本','≤售价','行标','RETAIL','PUBLISHED','1.0.0','数据标准组','2026-10-21 13:20:17'),(20,1,'DE_DEVICE_ID','device_id','设备标识','设备','STRING','32','字母数字','工业设备唯一编码','非空、唯一','行标','INDUSTRY','PUBLISHED','1.0.0','数据标准组','2026-10-21 13:20:17'),(21,1,'DE_METRIC_VALUE','metric_value','指标值','设备','DECIMAL','12,3','数值','设备采集的实时指标值','在量程范围内','行标','INDUSTRY','PUBLISHED','1.0.0','数据标准组','2026-10-21 13:20:17'),(22,1,'DE_COLLECT_TIME','collect_time','采集时间','设备','TIMESTAMP','19','yyyy-MM-dd HH:mm:ss','指标采集时间戳','延迟≤5分钟','行标','INDUSTRY','PUBLISHED','1.0.0','数据标准组','2026-10-21 13:20:17'),(23,1,'DE_TRADE_NO','trade_no','交易号','交易','STRING','64','字母数字','支付渠道交易流水号','唯一','行标','FINANCE','PUBLISHED','1.0.0','数据标准组','2026-10-21 13:20:17'),(24,1,'DE_REG_TIME','reg_time','注册时间','客户','TIMESTAMP','19','yyyy-MM-dd HH:mm:ss','客户注册时间','不得晚于当前时间','行标','RETAIL','PUBLISHED','1.0.0','数据标准组','2026-10-21 13:20:17'),(25,1,'DE_STAT_DATE','stat_date','统计日期','公共','DATE','10','yyyy-MM-dd','汇总数据的统计日期','非空','国标','GOV','PUBLISHED','1.0.0','数据标准组','2026-10-21 13:20:17'),(26,1,'DE_REGION','region','区域','公共','STRING','32','枚举','经营区域划分','引用区域字典','行标','RETAIL','PUBLISHED','1.0.0','数据标准组','2026-10-21 13:20:17'),(27,1,'DE_CHANNEL','channel','渠道','公共','STRING','32','枚举','业务发生渠道','引用渠道字典','行标','RETAIL','PUBLISHED','1.0.0','数据标准组','2026-10-21 13:20:17'),(28,1,'DE_REFUND_RATE','refund_rate','退款率','交易','DECIMAL','8,4','比率','退款金额占销售额比例','0~1','行标','FINANCE','PUBLISHED','1.0.0','数据标准组','2026-10-21 13:20:17'),(29,1,'DE_ACTIVE_FLAG','is_valid','有效标志','公共','INT','1','0/1','记录是否有效','仅取 0 或 1','行标','GOV','PUBLISHED','1.0.0','数据标准组','2026-10-21 13:20:17'),(30,1,'DE_OWNER','owner','责任人','公共','STRING','64','中文','数据对象责任人','非空','行标','GOV','PUBLISHED','1.0.0','数据标准组','2026-10-21 13:20:17');
