INSERT INTO `svc_api` (`id`, `tenant_id`, `code`, `name`, `api_path`, `method`, `version`, `status`, `category`, `sql_text`, `params`, `owner`, `app_code`, `auth_type`, `rate_limit`, `timeout_ms`, `mask_enabled`, `call_count`, `avg_ms`, `description`, `create_time`, `publish_time`, `industry`) VALUES (1,1,'API-CUST-PROFILE','客户画像查询','/customer/profile','GET','v1','PUBLISHED','客户服务','SELECT customer_id, cust_name, gender, city, phone, email, member_level, reg_time FROM ods_customer WHERE customer_id=\'${customerId}\'','[{\"name\":\"customerId\",\"type\":\"string\",\"required\":true,\"desc\":\"客户标识\"}]','数据服务组','APP-OPS','AKSK',200,3000,1,259,100.30,'按客户标识返回画像信息，phone/email 按脱敏策略输出','2026-10-01 13:20:53','2026-10-06 13:20:53','GOV'),(2,1,'API-SALES-REGION','区域销售达成查询','/sales/region','GET','v1','PUBLISHED','经营分析','SELECT stat_date, region, sales_amount, target_amount, completion_rate FROM dws_region_sales WHERE stat_date=\'${statDate}\' ORDER BY region','[{\"name\":\"statDate\",\"type\":\"date\",\"required\":true,\"desc\":\"统计日期 yyyy-MM-dd\"}]','数据服务组','APP-OPS','AKSK',500,3000,1,300,103.35,'返回指定日期的区域销售与目标达成','2026-10-01 13:20:53','2026-10-06 13:20:53','GOV'),(3,1,'API-ORDER-LIST','订单列表查询','/order/list','GET','v1','PUBLISHED','交易查询','SELECT order_id, customer_id, product_name, amount, status, region, order_time FROM ods_order ORDER BY order_time DESC LIMIT ${limit}','[{\"name\":\"limit\",\"type\":\"int\",\"required\":false,\"desc\":\"返回条数，默认50，上限500\"}]','数据服务组','APP-OPS','AKSK',100,3000,1,360,105.11,'按时间倒序返回订单明细，供对账与运营使用','2026-10-01 13:20:53','2026-10-06 13:20:53','GOV'),(4,1,'API-DEVICE-METRIC','设备时序指标查询','/device/metrics','GET','v1','PUBLISHED','工业互联','SELECT device_id, workshop, metric_name, metric_value, unit, collect_time FROM ods_device_metric WHERE device_id=\'${deviceId}\' AND metric_name=\'${metric}\' ORDER BY collect_time DESC LIMIT 100','[{\"name\":\"deviceId\",\"type\":\"string\",\"required\":true,\"desc\":\"设备编码\"},{\"name\":\"metric\",\"type\":\"string\",\"required\":true,\"desc\":\"指标名称\"}]','数据服务组','APP-FIN','AKSK',300,3000,1,420,100.89,'设备实时指标，供能耗分析与预测性维护','2026-10-01 13:20:53','2026-10-06 13:20:53','GOV'),(5,1,'API-QUALITY-TOP','数据质量排名','/quality/top','GET','v1','PUBLISHED','质量运营','SELECT t.name AS table_name, t.cn_name, t.quality_score, t.sensitive_level FROM md_table t ORDER BY t.quality_score DESC LIMIT ${limit}','[{\"name\":\"limit\",\"type\":\"int\",\"required\":false,\"desc\":\"返回条数\"}]','数据服务组','APP-GOV','AKSK',60,3000,1,180,102.62,'按质量评分返回资产排名，供治理运营看板','2026-10-01 13:20:53','2026-10-06 13:20:53','GOV'),(6,1,'API-GOV-POP','政务人口核查','/population/check','GET','v1','PUBLISHED','政务共享','SELECT COUNT(*) AS total, SUM(CASE WHEN id_card IS NULL THEN 1 ELSE 0 END) AS missing_id_card, SUM(CASE WHEN LENGTH(id_card)<>18 THEN 1 ELSE 0 END) AS invalid_id_card FROM ods_gov_population','[]','数据服务组','APP-GOV','AKSK',30,3000,1,240,101.48,'人口基础库证件完备性核查结果','2026-10-01 13:20:53','2026-10-06 13:20:53','GOV'),(7,1,'API-CUST-SCORE','客户价值分层查询','/customer/value-level','POST','v1','PUBLISHED','客户运营','SELECT customer_id, total_amount, order_cnt, value_level FROM dws_customer_value WHERE value_level=\'${level}\' ORDER BY total_amount DESC LIMIT 200','[{\"name\":\"level\",\"type\":\"string\",\"required\":true,\"desc\":\"高价值/中价值/普通\"}]','数据服务组','APP-OPS','AKSK',120,3000,1,0,0.00,'按价值分层拉取客户清单，待安全评审','2026-10-01 13:20:53','2026-10-21 14:00:33','GOV'),(8,1,'API-RAW-SQL','自助取数（草稿）','/adhoc/query','POST','v1','DRAFT','自助分析','SELECT * FROM ${table} LIMIT 100','[{\"name\":\"table\",\"type\":\"string\",\"required\":true,\"desc\":\"表名\"}]','数据服务组','APP-OPS','AKSK',10,3000,1,0,0.00,'自助取数能力，需接入沙箱与字段权限后发布','2026-10-01 13:20:53',NULL,'GOV');
/*!40000 ALTER TABLE `svc_api` ENABLE KEYS */;

