INSERT INTO `svc_api_version` (`id`, `api_id`, `version`, `sql_text`, `params`, `change_note`, `operator`, `create_time`) VALUES (1,1,'v1','SELECT customer_id, cust_name, gender, city, phone, email, member_level, reg_time FROM ods_customer WHERE customer_id=\'${customerId}\'','[{\"name\":\"customerId\",\"type\":\"string\",\"required\":true,\"desc\":\"客户标识\"}]','初始版本','数据服务组','2026-10-01 13:20:53'),(2,2,'v1','SELECT stat_date, region, sales_amount, target_amount, completion_rate FROM dws_region_sales WHERE stat_date=\'${statDate}\' ORDER BY region','[{\"name\":\"statDate\",\"type\":\"date\",\"required\":true,\"desc\":\"统计日期 yyyy-MM-dd\"}]','初始版本','数据服务组','2026-10-01 13:20:53'),(3,3,'v1','SELECT order_id, customer_id, product_name, amount, status, region, order_time FROM ods_order ORDER BY order_time DESC LIMIT ${limit}','[{\"name\":\"limit\",\"type\":\"int\",\"required\":false,\"desc\":\"返回条数，默认50，上限500\"}]','初始版本','数据服务组','2026-10-01 13:20:53'),(4,4,'v1','SELECT device_id, workshop, metric_name, metric_value, unit, collect_time FROM ods_device_metric WHERE device_id=\'${deviceId}\' AND metric_name=\'${metric}\' ORDER BY collect_time DESC LIMIT 100','[{\"name\":\"deviceId\",\"type\":\"string\",\"required\":true,\"desc\":\"设备编码\"},{\"name\":\"metric\",\"type\":\"string\",\"required\":true,\"desc\":\"指标名称\"}]','初始版本','数据服务组','2026-10-01 13:20:53'),(5,5,'v1','SELECT t.name AS table_name, t.cn_name, t.quality_score, t.sensitive_level FROM md_table t ORDER BY t.quality_score DESC LIMIT ${limit}','[{\"name\":\"limit\",\"type\":\"int\",\"required\":false,\"desc\":\"返回条数\"}]','初始版本','数据服务组','2026-10-01 13:20:53'),(6,6,'v1','SELECT COUNT(*) AS total, SUM(CASE WHEN id_card IS NULL THEN 1 ELSE 0 END) AS missing_id_card, SUM(CASE WHEN LENGTH(id_card)<>18 THEN 1 ELSE 0 END) AS invalid_id_card FROM ods_gov_population','[]','初始版本','数据服务组','2026-10-01 13:20:53'),(7,7,'v1','SELECT customer_id, total_amount, order_cnt, value_level FROM dws_customer_value WHERE value_level=\'${level}\' ORDER BY total_amount DESC LIMIT 200','[{\"name\":\"level\",\"type\":\"string\",\"required\":true,\"desc\":\"高价值/中价值/普通\"}]','初始版本','数据服务组','2026-10-01 13:20:53'),(8,8,'v1','SELECT * FROM ${table} LIMIT 100','[{\"name\":\"table\",\"type\":\"string\",\"required\":true,\"desc\":\"表名\"}]','初始版本','数据服务组','2026-10-01 13:20:53'),(9,7,'v1','SELECT customer_id, total_amount, order_cnt, value_level FROM dws_customer_value WHERE value_level=\'${level}\' ORDER BY total_amount DESC LIMIT 200','[{\"name\":\"level\",\"type\":\"string\",\"required\":true,\"desc\":\"高价值/中价值/普通\"}]','发布上线','admin','2026-10-21 14:00:33');
